package com.oms.order.service;

import org.junit.jupiter.api.*;
import java.time.LocalDateTime;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;

class OrderBackfillServiceTest {
    OrderRepositoryTest fixture;OrderRepository repository;OrderBackfillService service;
    static final String COMPANY=OrderRepositoryTest.COMPANY,LEASE=OrderRepositoryTest.LEASE;
    @BeforeAll static void setup(){OrderRepositoryTest.start();}
    @AfterAll static void close(){OrderRepositoryTest.stop();}
    @BeforeEach void seed(){fixture=new OrderRepositoryTest();fixture.clear();OrderRepositoryTest.db.update("DELETE FROM oms_order_pull_item");repository=OrderRepositoryTest.repository;ConfiguredPushReader push=mock(ConfiguredPushReader.class);when(push.configured(COMPANY,"fixture")).thenReturn(true);service=new OrderBackfillService(repository,push);}
    Map<String,Object> input(String mode){Map<String,Object> body=new LinkedHashMap<>();body.put("mode",mode);body.put("channel_ids",Collections.singletonList(1));return body;}
    Map<String,Object> byTid(String... ids){Map<String,Object> body=input("TID");body.put("tids",Arrays.asList(ids));return body;}
    long submit(Map<String,Object> input){return ((Number)((List<?>)service.submit(COMPANY,input,"tester").get("task_ids")).get(0)).longValue();}
    Map<String,Object> source(String tid){Map<String,Object> row=fixture.row("2026-10-01 01:00:00",TmallOrderParserTest.payload("25"));row.put("tid",tid);return row;}
    Map<String,Object> next(){return repository.nextTask(COMPANY,1,LEASE);}
    List<Map<String,Object>> results(long id){return (List<Map<String,Object>>)service.items(COMPANY,id,"",1,100).getRows();}
    @Test void longTimeRangeIsAcceptedAndFutureEndClipsToServerTimeIdempotently(){Map<String,Object> b=input("TIME");b.put("start_time",LocalDateTime.now().minusDays(150).format(TIME));b.put("end_time",LocalDateTime.now().plusDays(1).format(TIME));b.put("request_key","REQUEST_CLIPPED_12345");Map<String,Object> first=service.submit(COMPANY,b,"tester");assertEquals(true,first.get("range_clamped"));assertFalse(time(text(first,"end_time")).isAfter(LocalDateTime.now()));assertEquals(first.get("task_ids"),service.submit(COMPANY,b,"tester").get("task_ids"));assertEquals(first.get("end_time"),service.submit(COMPANY,b,"tester").get("end_time"));assertEquals("2026-10-01 00:00:00",text(repository.config(COMPANY,1),"cursor_time"));}
    @Test void invalidFutureOrReversedRangeIsRejectedWithSpecificMessage(){Map<String,Object> b=input("TIME");b.put("start_time",LocalDateTime.now().plusHours(1).format(TIME));b.put("end_time",LocalDateTime.now().plusHours(2).format(TIME));assertTrue(assertThrows(IllegalArgumentException.class,()->submit(b)).getMessage().contains("当前时间"));b.put("start_time","2026-10-02 00:00:00");b.put("end_time","2026-10-01 00:00:00");assertTrue(assertThrows(IllegalArgumentException.class,()->submit(b)).getMessage().contains("早于"));}
    @Test void tidNormalizationPreservesPrecisionAndRejectsNumericJsonAndOversizedBatches(){assertEquals(Arrays.asList("9007199254740993","987654321012345678"),OrderBackfillService.tids("9007199254740993，987654321012345678\n9007199254740993"));assertThrows(IllegalArgumentException.class,()->OrderBackfillService.tids(Arrays.asList(9007199254740993L)));assertThrows(IllegalArgumentException.class,()->OrderBackfillService.tids("12e3"));assertThrows(IllegalArgumentException.class,()->OrderBackfillService.tids("9223372036854775808"));List<String> many=new ArrayList<>();for(int i=1;i<=101;i++)many.add(String.valueOf(i));assertThrows(IllegalArgumentException.class,()->OrderBackfillService.tids(many));}
    @Test void exactRequestDeduplicatesAndChangingItsContentRejects(){Map<String,Object> b=byTid("9007199254740993","12345","12345");b.put("request_key","REQUEST_TID_1234567");long id=submit(b);b.put("tids",Arrays.asList("12345","9007199254740993"));assertEquals(id,submit(b));assertEquals(2,results(id).size());b.put("tids",Arrays.asList("22222"));assertThrows(IllegalArgumentException.class,()->submit(b));}
    @Test void tidTaskSeparatesNewSkippedAndNotFoundWithoutAdvancingAutomaticCursor(){long first=submit(byTid("987654321012345678"));repository.page(COMPANY,1,LEASE,next(),Arrays.asList(source("987654321012345678")),50);assertEquals("NEW",results(first).get(0).get("result"));long second=submit(byTid("987654321012345678","9007199254740993"));repository.page(COMPANY,1,LEASE,next(),Arrays.asList(source("987654321012345678")),50);List<Map<String,Object>> rows=results(second);assertEquals(new HashSet<>(Arrays.asList("SKIPPED","NOT_FOUND")),new HashSet<>(Arrays.asList(text(rows.get(0),"result"),text(rows.get(1),"result"))));assertEquals(1,fixture.n("SELECT COUNT(*) FROM oms_platform_order"));assertEquals("2026-10-01 00:00:00",text(repository.config(COMPANY,1),"cursor_time"));assertEquals("SUCCESS",service.task(COMPANY,second).get("status"));}
    @Test void failedRowRollsBackAloneAndRetryIncludesOnlyFailedIds(){long id=submit(byTid("12345","987654321012345678","9007199254740993"));Map<String,Object> bad=source("12345");bad.put("seller_nick","another seller");repository.page(COMPANY,1,LEASE,next(),Arrays.asList(bad,source("987654321012345678")),50);assertEquals("PARTIAL",service.task(COMPANY,id).get("status"));assertEquals(1,fixture.n("SELECT COUNT(*) FROM oms_platform_order"));List<Map<String,Object>> rows=results(id);long failed=number(rows.stream().filter(r->"FAILED".equals(r.get("result"))).findFirst().get(),"id");Map<String,Object> retry=service.retryFailures(COMPANY,id,"tester",Collections.singletonList(failed));long fresh=((Number)((List<?>)retry.get("task_ids")).get(0)).longValue();assertEquals("12345",results(fresh).get(0).get("platform_tid"));assertEquals(1,results(fresh).size());assertEquals(3,results(id).size());assertEquals("PARTIAL",service.task(COMPANY,id).get("status"));}
    @Test void pendingOrForeignItemsCannotBeRetriedOrViewed(){long id=submit(byTid("12345"));assertThrows(IllegalArgumentException.class,()->service.task("OTHER",id));assertThrows(IllegalArgumentException.class,()->service.items("OTHER",id,"",1,20));assertThrows(IllegalArgumentException.class,()->service.retryFailures(COMPANY,id,"tester"));repository.page(COMPANY,1,LEASE,next(),Collections.emptyList(),50);assertThrows(IllegalArgumentException.class,()->service.retryFailures(COMPANY,id,"tester"));}
    @Test void timeTasksAdvanceOneDailyWindowAtATimeIncludingEmptyDays(){Map<String,Object> b=input("TIME");b.put("start_time","2026-10-01 10:00:00");b.put("end_time","2026-10-03 12:00:00");long id=submit(b);Map<String,Object> first=next();assertEquals("2026-10-02 10:00:00",OrderBackfillService.windowEnd(first));repository.page(COMPANY,1,LEASE,first,Collections.emptyList(),50);assertEquals("RUNNING",service.task(COMPANY,id).get("status"));assertEquals("2026-10-02 10:00:00",service.task(COMPANY,id).get("page_time"));repository.page(COMPANY,1,LEASE,next(),Collections.emptyList(),50);repository.page(COMPANY,1,LEASE,next(),Collections.emptyList(),50);assertEquals("SUCCESS",service.task(COMPANY,id).get("status"));assertEquals("2026-10-03 12:00:00",service.task(COMPANY,id).get("page_time"));assertEquals("2026-10-01 00:00:00",text(repository.config(COMPANY,1),"cursor_time"));}
    @Test void connectionExhaustionMarksOnlyPendingTidsFailedAndAllowsTargetedRetry(){long id=submit(byTid("12345","9007199254740993"));next();for(int i=0;i<5;i++)repository.taskFailed(COMPANY,1,LEASE,id,"来源查询暂不可用");assertEquals("FAILED",service.task(COMPANY,id).get("status"));assertTrue(results(id).stream().allMatch(r->"FAILED".equals(r.get("result"))));assertNotNull(service.retryFailures(COMPANY,id,"tester").get("task_ids"));}
    @Test void convertedOrderChangesRequireReviewAndNeverOverwriteBusinessLines(){long first=submit(byTid("987654321012345678"));Map<String,Object> row=source("987654321012345678");repository.page(COMPANY,1,LEASE,next(),Arrays.asList(row),50);long platform=number(results(first).get(0),"platform_order_id");repository.snapshot(COMPANY,platform,LEASE);long business=repository.insert("INSERT INTO oms_order(company_code,order_sn,channel_id,platform_order_id,platform_tid,inventory_status,payment) VALUES ('VERIFY','SO_PROTECTED',1,?,'987654321012345678','RESERVED',25)",platform);repository.db().update("UPDATE oms_platform_order SET demand_registered=1,business_order_id=?,conversion_status='SUCCESS' WHERE id=?",business,platform);repository.db().update("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,reserved_quantity) VALUES ('VERIFY',?,'OID','SKU','goods',8,25,8)",business);long later=submit(byTid("987654321012345678"));row.put("jdp_modified","2026-10-02 01:00:00");row.put("jdp_response",TmallOrderParserTest.payload("30"));repository.page(COMPANY,1,LEASE,next(),Arrays.asList(row),50);assertEquals("CHANGE_PENDING",results(later).get(0).get("result"));assertEquals(1,fixture.n("SELECT change_pending FROM oms_platform_order WHERE id="+platform));assertEquals(8,fixture.n("SELECT reserved_quantity FROM oms_order_line WHERE order_id="+business));assertEquals(25,fixture.n("SELECT payment FROM oms_order WHERE id="+business));assertEquals(TmallOrderParserTest.payload("25"),repository.raw(COMPANY,platform).get("processing_payload"));}
    @Test void autoAndManualPaginationAreOrderedFairlyAndAutoStillOwnsItsCursor(){long auto=repository.newTask(COMPANY,1,"AUTO","2026-10-01 00:00:00","2026-10-02 00:00:00","test");long manual=submit(byTid("12345"));repository.db().update("UPDATE oms_order_pull_task SET next_retry_at=CASE WHEN id=? THEN '2026-10-01 00:00:00' ELSE '2026-10-01 00:01:00' END",auto);Map<String,Object> task=next();assertEquals(auto,number(task,"id"));repository.page(COMPANY,1,LEASE,task,Arrays.asList(source("987654321012345678")),1);assertEquals(manual,number(next(),"id"));}
}
